import json, subprocess, sys
from pathlib import Path
PARA = "Four score and seven years ago our fathers brought forth on this continent a new nation conceived in Liberty and dedicated to the proposition that all men are created equal"
ORDERS = "o1,alice,widget,3,2.50;o2,bob,gadget,1,10.00;o3,alice,gadget,2,10.00;o4,cara,widget,10,2.50;o5,bob,doohickey,4,7.25;o6,cara,gadget,1,10.00"
LOG = "09:15 login ann;09:20 login bo;09:41 logout ann;10:02 login cy;10:30 logout bo;11:11 login ann;11:45 logout cy;12:00 logout ann"
T = []
def t(id, cat, prompt, ref): T.append({"id": id, "cat": cat, "prompt": prompt, "ref": ref})
t("acronym", "strings", f"Take the text '{PARA}'. Print the acronym made from the first letter of every word that has at least 4 letters, in uppercase.", f"print(''.join(w[0].upper() for w in '{PARA}'.split() if len(w)>=4))")
t("char_runs", "strings", "For the string 'aaabccddddeffffffg', print the longest run of one repeated character as `char length`; on a tie keep the first.", "s='aaabccddddeffffffg';b=('',0);i=0\nwhile i<len(s):\n j=i\n while j<len(s) and s[j]==s[i]:j+=1\n if j-i>b[1]:b=(s[i],j-i)\n i=j\nprint(b[0],b[1])")
t("pig_latin", "strings", "Convert 'the quick brown fox jumps over the lazy dog' to Pig Latin: a word starting with a vowel (aeiou) gets 'way' appended; otherwise move the leading consonants to the end and add 'ay'. Print the words separated by spaces.", "def p(w):\n i=0\n while i<len(w) and w[i] not in 'aeiou':i+=1\n return w+'way' if i==0 else w[i:]+w[:i]+'ay'\nprint(' '.join(p(w) for w in 'the quick brown fox jumps over the lazy dog'.split()))")
t("isogram_words", "strings", f"From the words of '{PARA}' (lowercased), print, separated by spaces and in their original order without repeats, the words with at least 5 letters in which no letter appears twice.", f"o=[]\nfor w in '{PARA}'.lower().split():\n if len(w)>=5 and len(set(w))==len(w) and w not in o:o.append(w)\nprint(' '.join(o))")
t("order_totals", "parsing", f"Orders are given as '{ORDERS}' (semicolon-separated records of id,customer,item,quantity,unit price). Print each customer's total spend as `customer total` with 2 decimals, highest total first, ties alphabetical.", f"d={{}}\nfor r in '{ORDERS}'.split(';'):\n i,c,it,q,p=r.split(',');d[c]=d.get(c,0)+int(q)*float(p)\nfor c,v in sorted(d.items(),key=lambda x:(-x[1],x[0])):print(c,f'{{v:.2f}}')")
t("session_minutes", "parsing", f"A log is '{LOG}' (semicolon-separated `HH:MM action user`). Each login is followed later by that user's logout. Print each user's total logged-in minutes as `user minutes`, sorted by user name.", f"o={{}};tot={{}}\nfor e in '{LOG}'.split(';'):\n tm,a,u=e.split();h,m=map(int,tm.split(':'));x=h*60+m\n if a=='login':o[u]=x\n else:tot[u]=tot.get(u,0)+x-o.pop(u)\nfor u in sorted(tot):print(u,tot[u])")
t("ini_sections", "parsing", "Parse the INI text '[db]\\nhost=local\\nport=5432\\n[web]\\nport=8080\\nworkers=4\\n[db]\\nuser=admin' (the \\n are line breaks; a repeated section adds to the earlier one). Print each section as `name: key=value,key=value` with keys sorted, sections sorted by name.", "s='[db]\\nhost=local\\nport=5432\\n[web]\\nport=8080\\nworkers=4\\n[db]\\nuser=admin';d={};c=None\nfor l in s.split('\\n'):\n if l.startswith('['):c=l[1:-1];d.setdefault(c,{})\n else:k,v=l.split('=');d[c][k]=v\nfor n in sorted(d):print(n+': '+','.join(f'{k}={d[n][k]}' for k in sorted(d[n])))")
t("rpn_eval", "parsing", "Evaluate each Reverse Polish Notation expression with integers and + - * (no division): '3 4 + 2 *', '5 1 2 + 4 * + 3 -', '2 3 4 * 5 - *', '9 8 7 6 - - -'. Print each result on its own line.", "for e in ['3 4 + 2 *','5 1 2 + 4 * + 3 -','2 3 4 * 5 - *','9 8 7 6 - - -']:\n s=[]\n for k in e.split():\n  if k in '+-*':b=s.pop();a=s.pop();s.append(a+b if k=='+' else a-b if k=='-' else a*b)\n  else:s.append(int(k))\n print(s[0])")
t("amicable_sum", "math", "Print the sum of all amicable numbers below 10000 (a and b are amicable when a != b, the proper-divisor sum of a is b, and that of b is a).", "N=10000;d=[0]*N\nfor i in range(1,N):\n for j in range(2*i,N,i):d[j]+=i\nprint(sum(a for a in range(2,N) if d[a]<N and d[a]!=a and d[d[a]]==a))")
t("totient_sum", "math", "Print the sum of Euler's totient phi(n) for n from 1 to 100000.", "N=100000;p=list(range(N+1))\nfor i in range(2,N+1):\n if p[i]==i:\n  for j in range(i,N+1,i):p[j]-=p[j]//i\nprint(sum(p[1:]))")
t("digit_sum_power", "math", "Among numbers a**b with 1 <= a, b < 20 that fit in a signed 64-bit integer, print the largest digit sum, then a space, then the smallest such a**b achieving it.", "b=(0,0)\nfor a in range(1,20):\n for e in range(1,20):\n  v=a**e\n  if v<2**63:\n   s=sum(map(int,str(v)))\n   if s>b[0] or s==b[0] and v<b[1]:b=(s,v)\nprint(b[0],b[1])")
t("goldbach_count", "math", "For each even n in 10, 100, 1000, 10000, print `n count` where count is the number of ways to write n as p + q with primes p <= q.", "M=10001;s=[1]*M;s[0]=s[1]=0\nfor i in range(2,101):\n if s[i]:\n  for j in range(i*i,M,i):s[j]=0\nfor n in [10,100,1000,10000]:print(n,sum(1 for p in range(2,n//2+1) if s[p] and s[n-p]))")
t("lis_length", "dp", "For the sequence x(0)=7, x(i+1)=(x(i)*1103515245+12345) mod 2147483648, take x(1)..x(2000) mod 1000. Print the length of the longest strictly increasing subsequence.", "import bisect\nx=7;a=[]\nfor _ in range(2000):x=(x*1103515245+12345)%2147483648;a.append(x%1000)\nt=[]\nfor v in a:\n i=bisect.bisect_left(t,v)\n if i==len(t):t.append(v)\n else:t[i]=v\nprint(len(t))")
t("grid_paths_blocked", "dp", "In a 12x12 grid, count monotone paths (right or down moves) from the top-left to the bottom-right cell, where cell (r, c) is blocked when (r*7 + c*3) % 11 == 5. Print the count.", "n=12;g=[[0]*n for _ in range(n)]\nfor r in range(n):\n for c in range(n):\n  if (r*7+c*3)%11==5:continue\n  g[r][c]=1 if r==0 and c==0 else (g[r-1][c] if r else 0)+(g[r][c-1] if c else 0)\nprint(g[n-1][n-1])")
t("word_break", "dp", "Using the dictionary apple, pen, applepen, pine, pineapple, cats, dog, sand, and, cat, print for each of 'pineapplepenapple', 'catsandog', 'catsanddog', 'applepenpine' the number of ways it can be split into dictionary words, one per line as `word count`.", "D={'apple','pen','applepen','pine','pineapple','cats','dog','sand','and','cat'}\nfor s in ['pineapplepenapple','catsandog','catsanddog','applepenpine']:\n w=[1]+[0]*len(s)\n for i in range(1,len(s)+1):w[i]=sum(w[j] for j in range(i) if s[j:i] in D)\n print(s,w[-1])")
t("min_coins", "dp", "With coin values 1, 7, 10, 22, print the minimum number of coins needed for each amount 14, 30, 59, 100, 999, separated by spaces.", "c=[1,7,10,22];M=1000;f=[0]+[10**9]*M\nfor a in range(1,M):f[a]=min(f[a-k]+1 for k in c if k<=a)\nprint(' '.join(str(f[a]) for a in [14,30,59,100,999]))")
t("islands", "search", "The grid rows are '11000110', '11001100', '00100001', '00011011', '10000011', '11110000' ('1' is land). Print the number of islands (4-connected) and the size of the largest island, separated by a space.", "g=['11000110','11001100','00100001','00011011','10000011','11110000'];R=len(g);C=len(g[0]);s=set();n=0;b=0\nfor r in range(R):\n for c in range(C):\n  if g[r][c]=='1' and (r,c) not in s:\n   n+=1;st=[(r,c)];s.add((r,c));k=0\n   while st:\n    y,x=st.pop();k+=1\n    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):\n     a,e=y+dy,x+dx\n     if 0<=a<R and 0<=e<C and g[a][e]=='1' and (a,e) not in s:s.add((a,e));st.append((a,e))\n   b=max(b,k)\nprint(n,b)")
t("word_ladder", "search", "Words: cold, cord, card, ward, warm, word, worm, wore, core, care, ware, wold. Moving between words that differ in exactly one letter, print the length of the shortest path from cold to warm counting both ends.", "from collections import deque\nW='cold cord card ward warm word worm wore core care ware wold'.split()\nd={'cold':1};q=deque(['cold'])\nwhile q:\n w=q.popleft()\n for v in W:\n  if v not in d and sum(a!=b for a,b in zip(w,v))==1:d[v]=d[w]+1;q.append(v)\nprint(d['warm'])")
t("subset_target", "search", "Count the subsets of [3, 34, 4, 12, 5, 2, 27, 18, 9, 11, 7, 15, 21, 6, 8] whose sum is exactly 50. Print the count.", "a=[3,34,4,12,5,2,27,18,9,11,7,15,21,6,8];print(sum(1 for m in range(1<<len(a)) if sum(a[i] for i in range(len(a)) if m>>i&1)==50))")
t("sudoku_row_check", "search", "Fill a 4x4 Latin square (each row and column holds 1-4 once) whose first row is 1 2 3 4, by backtracking that tries values in increasing order cell by cell. Print the total number of such squares, then the first one found as four lines of space-separated numbers.", "import itertools\nsq=[]\ng=[[1,2,3,4]]+[[0]*4 for _ in range(3)]\ndef f(i):\n if i==16:sq.append([r[:] for r in g]);return\n r,c=divmod(i,4)\n if r==0:return f(i+1)\n for v in range(1,5):\n  if v not in g[r][:c] and all(g[k][c]!=v for k in range(r)):g[r][c]=v;f(i+1);g[r][c]=0\nf(0);print(len(sq))\nfor r in sq[0]:print(*r)")
t("elevator", "sim", "An elevator starts at floor 0 and serves requests in order: 5, 2, 9, 9, 1, 7, 3. Moving one floor takes 2 seconds and each stop takes 5 seconds. Print the total time and the total floors traveled, separated by a space.", "f=0;t=0;d=0\nfor r in [5,2,9,9,1,7,3]:\n d+=abs(r-f);t+=2*abs(r-f)+5;f=r\nprint(t,d)")
t("bank_ledger", "sim", "Accounts start empty. Apply: deposit ann 100; deposit bob 50; withdraw ann 30; transfer ann bob 50; withdraw bob 200 (rejected when the balance is short); deposit cy 75; transfer bob cy 60. Print each account as `name balance` sorted by name, then the number of rejected operations.", "b={};rj=0\nops=[('d','ann',100),('d','bob',50),('w','ann',30),('t','ann','bob',50),('w','bob',200),('d','cy',75),('t','bob','cy',60)]\nfor o in ops:\n if o[0]=='d':b[o[1]]=b.get(o[1],0)+o[2]\n elif o[0]=='w':\n  if b.get(o[1],0)>=o[2]:b[o[1]]-=o[2]\n  else:rj+=1\n else:\n  if b.get(o[1],0)>=o[3]:b[o[1]]-=o[3];b[o[2]]=b.get(o[2],0)+o[3]\n  else:rj+=1\nfor k in sorted(b):print(k,b[k])\nprint(rj)")
t("cellular_rule30", "sim", "Run elementary cellular automaton rule 30 on a row of 31 cells with only the middle cell on, for 15 steps (cells beyond the edges are off). Print the number of on cells after the last step.", "n=31;c=[0]*n;c[15]=1\nfor _ in range(15):c=[(30>>((c[i-1] if i else 0)*4+c[i]*2+(c[i+1] if i<n-1 else 0)))&1 for i in range(n)]\nprint(sum(c))")
t("josephus", "sim", "41 people stand in a circle numbered 1 to 41; counting starts at person 1 and every 3rd person is removed. Print the numbers of the last two people remaining, in the order they would be removed.", "p=list(range(1,42));i=0;o=[]\nwhile p:\n i=(i+2)%len(p);o.append(p.pop(i))\nprint(o[-2],o[-1])")
t("compound_interest", "float", "Starting with 1000.00 at 4.5% annual interest compounded monthly, with 100.00 deposited at the end of each month, print the balance after each of years 1, 5 and 10 with 2 decimals, one per line.", "b=1000.0\nfor m in range(1,121):\n b=b*(1+0.045/12)+100\n if m in (12,60,120):print(f'{b:.2f}')")
t("newton_roots", "float", "Use Newton's method starting at x = 1.0 with 30 iterations to approximate the cube roots of 2, 10 and 100. Print each with 10 decimals on its own line.", "for a in [2,10,100]:\n x=1.0\n for _ in range(30):x-=(x**3-a)/(3*x*x)\n print(f'{x:.10f}')")
t("trapezoid_area", "float", "Integrate sin(x) * exp(-x / 3) from 0 to 10 with the trapezoid rule using 100000 intervals. Print the result with 8 decimals.", "import math\nn=100000;h=10/n;f=lambda x:math.sin(x)*math.exp(-x/3)\nprint(f'{h*(f(0)/2+f(10)/2+sum(f(i*h) for i in range(1,n))):.8f}')")
t("prime_sieve_count", "speed", "Count the primes below 20000000. Print the count.", "n=20000000;s=bytearray([1])*n;s[0]=s[1]=0\nfor i in range(2,int(n**.5)+1):\n if s[i]:s[i*i::i]=bytearray(len(range(i*i,n,i)))\nprint(sum(s))")
t("collatz_max_value", "speed", "For starting values below 300000, find the start whose Collatz sequence reaches the highest value. Print the start and that highest value, separated by a space.", "b=(0,0)\nfor s in range(1,300000):\n n=s;m=s\n while n!=1:\n  n=n//2 if n%2==0 else 3*n+1\n  if n>m:m=n\n if m>b[1]:b=(s,m)\nprint(b[0],b[1])")
t("pythagorean_count", "speed", "Count the Pythagorean triples a < b < c with a^2 + b^2 = c^2 and c <= 3000. Print the count.", "import math\nk=0\nfor a in range(1,3001):\n for b in range(a+1,3001):\n  c2=a*a+b*b;c=math.isqrt(c2)\n  if c>3000:break\n  if c*c==c2:k+=1\nprint(k)")
t("change_digits", "basic", "Print the integers from 1 to 60 whose digits are all different and whose digit sum is odd, separated by commas.", "print(','.join(str(n) for n in range(1,61) if len(set(str(n)))==len(str(n)) and sum(map(int,str(n)))%2))")
t("table_format", "basic", "Print a multiplication table for 1 to 6 where every number is right-aligned in a field of width 4 (rows on separate lines, no trailing spaces beyond the fields).", "for i in range(1,7):print(''.join(f'{i*j:4d}' for j in range(1,7)))")
if __name__ == "__main__":
    for x in T:
        r = subprocess.run([sys.executable, "-c", x["ref"]], capture_output=True, text=True, timeout=600)
        assert r.returncode == 0, (x["id"], r.stderr)
        x["expected"] = r.stdout
    json.dump(T, open(Path(__file__).parent / "tasks3.json", "w"), indent=1)
    print(len(T), "tasks;", {c: sum(1 for x in T if x["cat"] == c) for c in sorted({x["cat"] for x in T})})
